$project_name = Read-Host "Project name"

$composer = @"
{
    "name": "$project_name",
    "description": "Starter PHP moderne sans framework — routeur + PDO + config .env",
    "type": "project",
    "require": {
        "php": ">=8.1",
        "nikic/fast-route": "^1.3",
        "vlucas/phpdotenv": "^5.6"
    },
    "autoload": {
        "psr-4": {
            "App\\": "src/"
        }
    },
    "config": {
        "optimize-autoloader": true
    }
}
"@

# 1. Création et déplacement dans le dossier projet
New-Item -ItemType Directory -Path $project_name -Force | Out-Null
Set-Location $project_name

$base64 = ""

# Emplacements des fichiers
$zipPath = Join-Path -Path $ExecutionContext.SessionState.Path.CurrentFileSystemLocation -ChildPath "archive.zip"
$composerPath = Join-Path -Path $ExecutionContext.SessionState.Path.CurrentFileSystemLocation -ChildPath "composer.json"

# 2. Conversion du Base64 en fichier ZIP
[System.IO.File]::WriteAllBytes($zipPath, [System.Convert]::FromBase64String($base64))

# 3. Extraction du ZIP via les API .NET
Add-Type -AssemblyName System.IO.Compression.FileSystem
[System.IO.Compression.ZipFile]::ExtractToDirectory($zipPath, $ExecutionContext.SessionState.Path.CurrentFileSystemLocation, $true)

# 4. Nettoyage de l'archive ZIP
Remove-Item -Path $zipPath -Force

# 5. Écriture du fichier composer.json
Set-Content -Path $composerPath -Value $composer -Encoding UTF8
